SOURCE_MAP = {item["key"]: item for item in SOURCES}

def get_sources(module_key: str | None = None, confidence: str | None = None):
    rows = SOURCES
    if module_key:
        rows = [s for s in rows if s["module_key"] == module_key]
    if confidence:
        rows = [s for s in rows if s["confidence"] == confidence]
    return [dict(s) for s in rows]
